-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/silver/silver_empi_pair.sql, analytics/dbt/models/silver/silver_empi_truth.sql. Do not edit.
-- Silver EMPI pair: one row per pair in the EMPI review queue (Binary/empi-review, published by empi/match.py run):
-- the score and what was decided. Clear no matches are not published, so they are not here either.
CREATE OR REPLACE TABLE silver_empi_pair AS
WITH doc AS (
    SELECT PARSE_JSON(BASE64_DECODE_STRING(raw:data::string)) AS doc
    FROM bronze_resources
    WHERE resource_type = 'Binary' AND resource_id = 'empi-review'
    QUALIFY ROW_NUMBER() OVER (PARTITION BY resource_id ORDER BY loaded_at DESC, bronze_id DESC) = 1
)
SELECT
    p.value:pair_id::string                   AS pair_id,
    p.value:a.id::string                      AS patient_a_id,
    p.value:b.id::string                      AS patient_b_id,
    p.value:a.source::string                  AS source_a,
    p.value:b.source::string                  AS source_b,
    TRY_CAST(p.value:score::string AS DOUBLE)                     AS score,
    p.value:status::string                    AS status,
    TRY_CAST(SUBSTR(p.value:decided_at::string, 1, 19) AS TIMESTAMP_NTZ)                 AS decided_at
FROM doc d , LATERAL FLATTEN(input => d.doc:pairs) p;

-- Silver EMPI truth: the ground truth of the seeded EMPI test set (Binary/empi-truth, from hl7v2/pipeline.py
-- empi-seed): which Riverside General registrations are copies of Synthea patients, and which only share a name.
CREATE OR REPLACE TABLE silver_empi_truth AS
WITH doc AS (
    SELECT PARSE_JSON(BASE64_DECODE_STRING(raw:data::string)) AS doc
    FROM bronze_resources
    WHERE resource_type = 'Binary' AND resource_id = 'empi-truth'
    QUALIFY ROW_NUMBER() OVER (PARTITION BY resource_id ORDER BY loaded_at DESC, bronze_id DESC) = 1
)
SELECT
    t.value:seed_id::string                   AS seed_patient_id,
    t.value:existing_id::string               AS existing_patient_id,
    t.value:kind::string                      AS kind,
    t.value:variations::string                AS variations,
    t.value:note::string                      AS note
FROM doc d , LATERAL FLATTEN(input => d.doc:pairs) t;
